package org.springframework.samples.petclinic.rest.function.owner;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;

import net.officefloor.plugin.variable.Out;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.DisposableEmailDomainException;
import org.springframework.samples.petclinic.rest.escalation.FutureRegistrationDateException;
import org.springframework.samples.petclinic.rest.escalation.InvalidEmailException;
import org.springframework.samples.petclinic.rest.escalation.InvalidPostcodeException;
import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
import org.springframework.samples.petclinic.rest.escalation.MissingOwnerFieldsException;
import org.springframework.web.bind.annotation.RequestBody;

/**
 * First step of {@code POST /api/owners}. Normalizes the address to its canonical form (see
 * {@link OwnerAddress}) and stores it back on the request, then rejects a request that is missing
 * or blank in any required field (firstName, lastName, address, city, telephone) — the address
 * being tested for blankness after normalization — with a 400 whose body lists the offending field
 * names. Then normalizes the telephone to E.164 form (see {@link
 * TelephoneE164}), storing the E.164 value back on the request so later steps persist and return
 * it; a telephone that cannot form valid E.164 is rejected with a 400. Finally, when a {@code
 * postcode} is supplied it is validated against the city's region (see {@link Postcode}); a
 * malformed or out-of-range postcode is rejected with a 400, while an absent postcode is accepted.
 * A supplied {@code registrationDate} later than the server date is rejected with a 400, while an
 * absent registration date (defaulted later to the server date) is accepted. Runs before
 * {@link BuildOwner} maps the body to an {@link
 * org.springframework.samples.petclinic.model.Owner}.
 */
public class ValidateNewOwner {

    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
            throws MissingOwnerFieldsException, InvalidTelephoneException, InvalidEmailException,
            InvalidPostcodeException, FutureRegistrationDateException, DisposableEmailDomainException {
        // Address may arrive structured (addressLine1 [+ addressLine2]) or as the flat 'address'.
        // The structured form is preferred whenever addressLine1 is non-blank; otherwise the flat
        // value is used (backward-compatible). Whichever fields are supplied are normalized, and the
        // flat 'address' everything downstream reads is composed from the structured fields when they
        // win: normalized addressLine1 plus, when addressLine2 is present, a space and normalized
        // addressLine2.
        String addressLine1 = OwnerAddress.normalize(request.getAddressLine1());
        if (!addressLine1.isEmpty()) {
            String addressLine2 = OwnerAddress.normalize(request.getAddressLine2());
            request.setAddressLine1(addressLine1);
            request.setAddressLine2(addressLine2.isEmpty() ? null : addressLine2);
            request.setAddress(addressLine2.isEmpty() ? addressLine1 : addressLine1 + " " + addressLine2);
        }
        else {
            request.setAddress(OwnerAddress.normalize(request.getAddress()));
        }
        List<String> missing = new ArrayList<>();
        if (isBlank(request.getFirstName())) {
            missing.add("firstName");
        }
        if (isBlank(request.getLastName())) {
            missing.add("lastName");
        }
        if (isBlank(request.getAddress())) {
            missing.add("address");
        }
        if (isBlank(request.getCity())) {
            missing.add("city");
        }
        if (isBlank(request.getTelephone())) {
            missing.add("telephone");
        }
        if (!missing.isEmpty()) {
            throw new MissingOwnerFieldsException(missing);
        }
        request.setTelephone(TelephoneE164.normalize(request.getTelephone()));
        request.setEmail(OwnerEmail.normalize(request.getEmail()));
        // Postcode is optional; when present it must be a 4-digit code valid for the city's region.
        Postcode.validate(request.getPostcode(), request.getCity());
        // Registration date is optional; when supplied it may be back-dated but never into the future.
        LocalDate registrationDate = request.getRegistrationDate();
        if (registrationDate != null && registrationDate.isAfter(LocalDate.now())) {
            throw new FutureRegistrationDateException(registrationDate);
        }
        validated.set(request);
    }

    private static boolean isBlank(String value) {
        return value == null || value.isBlank();
    }
}
